      setInfoMsg(svc.info);
      setPanel("info");
    } else {
      setPanel(svc.panel);
      setInfoMsg("");
    }
    setSidebarOpen(false);
  };

  return (
    <div style={s.app}>
      {/* ── Tagline bar ── */}
      <div style={s.taglineBar}>{BRAND.tagline}</div>

      {/* ── Navbar ── */}
      <nav style={s.nav}>
        <div style={s.navLeft}>
          {/* Hamburger */}
          <button style={s.hamburger} onClick={() => setSidebarOpen(!sidebarOpen)}
                  aria-label="Toggle menu">
            <span style={s.hLine}/><span style={s.hLine}/><span style={s.hLine}/>
          </button>
          {/* Logo + brand */}
          <div style={s.brandWrap}>
            <div style={s.logoCircle}>
              <img src="/logo.jpeg" alt="CD" style={s.logoImg}
                   onError={e => { e.target.style.display="none"; }}/>
            </div>
            <div>
              <div style={s.brandName}>{BRAND.name}</div>
              <div style={s.brandInit}>{BRAND.initiative}</div>
            </div>
          </div>
        </div>
        <div style={s.navRight}>
          <a href={BRAND.social.youtube}   target="_blank" rel="noopener noreferrer" style={s.socialA}>▶</a>
          <a href={BRAND.social.telegram}  target="_blank" rel="noopener noreferrer" style={s.socialA}>✈</a>
          <a href={BRAND.social.instagram} target="_blank" rel="noopener noreferrer" style={s.socialA}>📷</a>
          <BookSessionBtn />
        </div>
      </nav>

      {/* ── Overlay when sidebar open ── */}
      {sidebarOpen && (
        <div style={s.overlay} onClick={() => setSidebarOpen(false)}/>
      )}

      {/* ── Sidebar drawer ── */}
      <aside style={{ ...s.sidebar, transform: sidebarOpen ? "translateX(0)" : "translateX(-100%)" }}>
        <div style={s.sidebarHeader}>
          <span style={s.sidebarTitle}>Services</span>
          <button style={s.closeBtn} onClick={() => setSidebarOpen(false)}>✕</button>
        </div>

        {/* FREE section */}
        <div style={s.sectionLbl}>
          <span style={s.tagFree}>FREE</span> SERVICES
        </div>
        {SIDEBAR_SERVICES.filter(s => s.free).map(svc => (
          <SidebarItem key={svc.id} svc={svc} active={panel === svc.panel}
                       onClick={() => navigate(svc)} />
        ))}

        {/* PAID section */}
        <div style={{ ...s.sectionLbl, marginTop: 16 }}>
          <span style={s.tagPaid}>PREMIUM</span> SERVICES
        </div>
        {SIDEBAR_SERVICES.filter(s => !s.free).map(svc => (
          <SidebarItem key={svc.id} svc={svc} active={panel === "paid"}
                       onClick={() => navigate(svc)} />
        ))}
      </aside>

      {/* ── Hero ── */}
      <div style={s.hero}>
        <div style={s.heroBadge}>MHT-CET 2026 · MAHARASHTRA</div>
        <h1 style={s.heroTitle}>Find your perfect engineering college</h1>
        <p style={s.heroSub}>Personalized predictions · Safe, Moderate & Reach picks · Download as PDF</p>
        <div style={s.statsRow}>
          {[["650+","COLLEGES"],["95","BRANCHES"],["4","CAP ROUNDS"]].map(([n,l]) => (
            <div key={l} style={s.statItem}>
              <div style={s.statNum}>{n}</div>
              <div style={s.statLbl}>{l}</div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Main panel ── */}
      <div style={s.mainWrap}>
        {panel === "predictor" && <PredictorPanel />}
        {panel === "documents" && <DocumentsPanel />}
        {panel === "paid"      && <PaidPanel />}
        {panel === "contact"   && <ContactPanel />}
        {panel === "info"      && <InfoPanel msg={infoMsg} />}
      </div>

      <SiteFooter />

      {/* Floating WhatsApp — bottom-right, 100px from bottom */}
      <a href={`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(WHATSAPP_MSG)}`}
         target="_blank" rel="noopener noreferrer" style={s.whatsappFloat}
