// ═════════════════════════════════════════════════════════════════════════════
// MULTI-SELECT DROPDOWN
// ═════════════════════════════════════════════════════════════════════════════
function MultiSelect({ options, selected, onChange, placeholder }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  const toggle = v => onChange(selected.includes(v) ? selected.filter(x=>x!==v) : [...selected, v]);

  return (
    <div ref={ref} style={{ position:"relative" }}>
      <div onClick={()=>setOpen(!open)} style={s.msBox}>
        <span style={{ color: selected.length ? C.textDark : C.textLight, fontSize:14 }}>
          {selected.length ? `${selected.length} selected` : placeholder}
        </span>
        <span style={{ color:C.navy }}>▾</span>
      </div>
      {open && (
        <div style={s.msDropdown}>
          {options.map(o=>(
            <label key={o} style={s.msItem}>
              <input type="checkbox" checked={selected.includes(o)} onChange={()=>toggle(o)}
                     style={{ marginRight:8, accentColor:C.navy }}/>
              {o}
            </label>
          ))}
        </div>
      )}
      {selected.length>0 && (
        <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginTop:8 }}>
          {selected.map(t=>(
            <span key={t} style={s.msTag}>
              {t} <span onClick={()=>toggle(t)} style={{ cursor:"pointer", marginLeft:4 }}>×</span>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

